declare_lint ! { #[doc = " The `binary_asm_labels` lint detects the use of numeric labels containing only binary"] #[doc = " digits in the inline `asm!` macro."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,ignore (fails on non-x86_64)"] #[doc = " #![cfg(target_arch = \"x86_64\")]"] #[doc = ""] #[doc = " use std::arch::asm;"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     unsafe {"] #[doc = "         asm!(\"0: jmp 0b\");"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This will produce:"] #[doc = ""] #[doc = " ```text"] #[doc = " error: avoid using labels containing only the digits `0` and `1` in inline assembly"] #[doc = "  --> <source>:7:15"] #[doc = "   |"] #[doc = " 7 |         asm!(\"0: jmp 0b\");"] #[doc = "   |               ^ use a different label that doesn't start with `0` or `1`"] #[doc = "   |"] #[doc = "   = help: start numbering with `2` instead"] #[doc = "   = note: an LLVM bug makes these labels ambiguous with a binary literal number on x86"] #[doc = "   = note: see <https://github.com/llvm/llvm-project/issues/99547> for more information"] #[doc = "   = note: `#[deny(binary_asm_labels)]` on by default"] #[doc = " ```"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " An [LLVM bug] causes this code to fail to compile because it interprets the `0b` as a binary"] #[doc = " literal instead of a reference to the previous local label `0`. To work around this bug,"] #[doc = " don't use labels that could be confused with a binary literal."] #[doc = ""] #[doc = " This behavior is platform-specific to x86 and x86-64."] #[doc = ""] #[doc = " See the explanation in [Rust By Example] for more details."] #[doc = ""] #[doc = " [LLVM bug]: https://github.com/llvm/llvm-project/issues/99547"] #[doc = " [Rust By Example]: https://doc.rust-lang.org/nightly/rust-by-example/unsafe/asm.html#labels"] pub BINARY_ASM_LABELS , Deny , "labels in inline assembly containing only 0 or 1 digits" , }